USE MASTER
GO

IF EXISTS (SELECT * FROM sys.databases WHERE NAME = 'DB_Pets')
DROP DATABASE DB_Pets
GO

CREATE DATABASE DB_Pets
GO

USE DB_Pets
GO

-- creation of dif tables
CREATE TABLE [dbo].[Users] (
    [UserId] INT IDENTITY(1,1) PRIMARY KEY,
    [FirstName] NVARCHAR(100),
    [LastName] NVARCHAR(100),
    [Email] NVARCHAR(255)
)
GO

CREATE TABLE [dbo].[Phones] (
    [PhoneId] INT IDENTITY(1,1) PRIMARY KEY,
    [UserId] INT,
    [PhoneNumber] NVARCHAR(50)
)
GO

CREATE TABLE [dbo].[PetTypes] (
    [TypeId] INT IDENTITY(1,1) PRIMARY KEY,
    [TypeName] NVARCHAR(50)
)
GO

CREATE TABLE [dbo].[Breeds] (
    [BreedId] INT IDENTITY(1,1) PRIMARY KEY,
    [TypeId] INT,
    [BreedName] NVARCHAR(100)
)
GO

CREATE TABLE [dbo].[Locations] (
    [LocationId] INT IDENTITY(1,1) PRIMARY KEY,
    [LocationName] NVARCHAR(100)
)
GO

CREATE TABLE [dbo].[Pets] (
    [PetId] INT IDENTITY(1,1) PRIMARY KEY,
    [PetName] NVARCHAR(150),
    [TypeId] INT,
    [BreedId] INT,
    [LocationId] INT,
    [Age] INT,
    [Weight] DECIMAL(6,2),
    [Gender] NVARCHAR(20),
    [PetStory_Short] NVARCHAR(MAX),
	[PetStory_Long] NVARCHAR(MAX),
    [Status] NVARCHAR(50),
    [PosterUserId] INT,
    [Image] NVARCHAR(MAX) NOT NULL
)
GO

CREATE TABLE [dbo].[Adoptions] (
    [AdoptionId] INT IDENTITY(1,1) PRIMARY KEY,
    [PetId] INT,
    [AdopterUserId] INT,
    [AdopterPhoneId] INT,
    [AdoptionDate] DATETIME
)
GO

CREATE TABLE [dbo].[Donations] (
    [DonationId] INT IDENTITY(1,1) PRIMARY KEY,
    [DonorUserId] INT,
    [DonorPhoneId] INT,
    [Amount] DECIMAL(12,2),
    [DonationDate] DATETIME
)
GO

